// zod schemas + helpers for every IPC payload (no electron import; unit tested).

import { stat } from 'node:fs/promises'
import { basename, extname, isAbsolute, normalize } from 'node:path'
import { z } from 'zod'
import { OPTIONS } from '../shared/catalog'
import type { DroppedItem, JobRequest, OptionId } from '../shared/types'

export const MAX_INPUTS = 500
const MAX_PATH_LENGTH = 4096

/** Job ids are generated by renderers: short, URL/file-name safe. */
export const jobIdSchema = z.string().regex(/^[A-Za-z0-9_-]{1,64}$/, 'Invalid job id')

const optionIds = Object.keys(OPTIONS) as [OptionId, ...OptionId[]]
export const optionIdSchema = z.enum(optionIds)

/**
 * Windows device / extended-length namespaces (`\\.\`, `\\?\`, also written with forward
 * slashes) are refused (SEC-14): they address devices and bypass normal path parsing.
 * Plain UNC paths (`\\server\share\file`) ARE accepted, as a documented decision: files on
 * network shares are ordinary user files, and Explorer drops them with UNC paths.
 */
export function isDeviceNamespacePath(p: string): boolean {
  return /^[\\/]{2}[.?][\\/]/.test(p)
}

export const absolutePathSchema = z
  .string()
  .min(1)
  .max(MAX_PATH_LENGTH)
  .refine((p) => !p.includes('\0'), 'Invalid path')
  .refine((p) => !isDeviceNamespacePath(p), 'Invalid path')
  .refine((p) => isAbsolute(p), 'Path must be absolute')
  .transform((p) => normalize(p))
  .refine((p) => !isDeviceNamespacePath(p), 'Invalid path')

export const pathListSchema = z.array(absolutePathSchema).min(1).max(MAX_INPUTS)

export const jobRequestSchema = z
  .object({
    id: jobIdSchema,
    optionId: optionIdSchema,
    inputPaths: pathListSchema
  })
  .strict()

export const booleanSchema = z.boolean()

/** Friendly error for the renderer; ipcMain.handle forwards `message`. */
export class IpcInputError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'IpcInputError'
  }
}

export function parseOrThrow<T>(schema: z.ZodType<T>, value: unknown, what: string): T {
  const r = schema.safeParse(value)
  if (!r.success) throw new IpcInputError(`Invalid ${what}.`)
  return r.data
}

export async function describePath(p: string): Promise<DroppedItem> {
  let st
  try {
    st = await stat(p)
  } catch {
    throw new IpcInputError(`Can't find "${basename(p)}". It may have been moved or deleted.`)
  }
  const isDirectory = st.isDirectory()
  if (!isDirectory && !st.isFile()) throw new IpcInputError(`"${basename(p)}" is not a regular file.`)
  return {
    path: p,
    name: basename(p),
    ext: isDirectory ? '' : extname(p).replace(/^\./, '').toLowerCase(),
    isDirectory,
    // Folder sizes are not computed (could be huge); the engine measures what it needs.
    sizeBytes: isDirectory ? 0 : st.size
  }
}

export async function describePaths(raw: unknown): Promise<DroppedItem[]> {
  const paths = parseOrThrow(pathListSchema, raw, 'file list')
  return Promise.all(paths.map(describePath))
}

/** Validate a job request and check that every input exists. */
export async function validateJobRequest(raw: unknown): Promise<JobRequest> {
  const req = parseOrThrow(jobRequestSchema, raw, 'job request')
  await Promise.all(req.inputPaths.map(describePath))
  return req
}
